const Redis = require('ioredis');
const { createServer } = require('http');
const crypto = require('crypto');

const MAX_BODY_SIZE = 1 * 1024 * 1024; // 1MB limit to prevent memory-exhaustion DoS

class DistributedCacheClient {
  constructor(config) {
    this.cluster = new Redis.Cluster(config.nodes, {
      redisOptions: { password: config.password, tls: config.tls },
      scaleReads: 'slave'
    });
    this.queryCache = new Map();
    this.shutdownHandlers = [];
    this.isShuttingDown = false;
  }

  registerShutdown(handler) {
    this.shutdownHandlers.push(handler);
  }

  async gracefulShutdown(signal) {
    if (this.isShuttingDown) return;
    this.isShuttingDown = true;
    console.log(`Received ${signal}, starting graceful shutdown...`);
    for (const handler of this.shutdownHandlers) {
      await handler();
    }
    await this.cluster.quit();
    process.exit(0);
  }

  computeCacheKey(operationName, variables) {
    const normalized = this.normalizeQuery(operationName, variables);
    return crypto.createHash('sha256').update(normalized).digest('hex');
  }

  normalizeQuery(operationName, variables) {
    const sortedVars = Object.keys(variables).sort().reduce((acc, key) => {
      acc[key] = variables[key];
      return acc;
    }, {});
    return `${operationName}:${JSON.stringify(sortedVars)}`;
  }

  async getCachedResult(operationName, variables) {
    const key = this.computeCacheKey(operationName, variables);
    const cached = await this.cluster.get(key);
    if (cached) return JSON.parse(cached);
    return null;
  }

  async setCachedResult(operationName, variables, result, ttl = 300) {
    const key = this.computeCacheKey(operationName, variables);
    await this.cluster.setex(key, ttl, JSON.stringify(result));
  }
}

class GraphQLQueryResolver {
  constructor(cacheClient) {
    this.cache = cacheClient;
    this.allowedOperations = new Set([
      'GetUser', 'ListProducts', 'GetOrder', 'SearchItems'
    ]);
    this.fieldRestrictions = {
      User: ['id', 'name', 'email', 'createdAt'],
      Product: ['id', 'name', 'price', 'category'],
      Order: ['id', 'status', 'total', 'items']
    };
  }

  validateOperationName(name) {
    return this.allowedOperations.has(name);
  }

  sanitizeFieldSelection(typeName, fields) {
    const allowed = this.fieldRestrictions[typeName];
    if (!allowed) return [];
    return fields.filter(f => allowed.includes(f));
  }

  buildResolverQuery(operation, variables, selections) {
    const sanitizedSelections = selections.map(sel => {
      if (sel.typeName && sel.fields) {
        return {
          typeName: sel.typeName,
          fields: this.sanitizeFieldSelection(sel.typeName, sel.fields)
        };
      }
      return sel;
    });

    const queryParts = sanitizedSelections.map(sel => {
      return `{ ${sel.typeName} { ${sel.fields.join(' ')} } }`;
    });

    return { operation, variables, query: queryParts.join(' ') };
  }

  async resolveWithCache(operation, variables, selections, context) {
    if (!this.validateOperationName(operation)) {
      throw new Error(`Operation '${operation}' is not allowed`);
    }

    const cached = await this.cache.getCachedResult(operation, variables);
    if (cached) return cached;

    const resolved = this.buildResolverQuery(operation, variables, selections);
    const result = await this.executeQuery(resolved, context);

    await this.cache.setCachedResult(operation, variables, result);
    return result;
  }

  async executeQuery(resolved, context) {
    const parameterized = this.buildParameterizedQuery(resolved.query, resolved.variables);
    return await context.executor(parameterized.query, parameterized.params);
  }

  buildParameterizedQuery(query, variables) {
    const params = {};
    let paramIndex = 0;
    for (const [key, value] of Object.entries(variables)) {
      const paramName = `p${paramIndex++}`;
      params[paramName] = String(value).replace(/[{}()\[\]]/g, '');
    }
    return { query, params };
  }
}

const cacheClient = new DistributedCacheClient({
  nodes: [{ host: '127.0.0.1', port: 6380 }],
  password: process.env.REDIS_PASSWORD,
  tls: process.env.NODE_ENV === 'production'
});

const resolver = new GraphQLQueryResolver(cacheClient);

const server = createServer(async (req, res) => {
  if (req.method !== 'POST' || req.url !== '/graphql') {
    res.writeHead(404);
    res.end();
    return;
  }

  let body = '';
  let aborted = false;
  req.on('data', chunk => {
    if (aborted) return;
    body += chunk;
    if (body.length > MAX_BODY_SIZE) {
      aborted = true;
      res.writeHead(413, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Payload too large' }));
      req.destroy();
    }
  });
  req.on('end', async () => {
    if (aborted) return;
    try {
      const { operation, variables, selections } = JSON.parse(body);
      const context = {
        executor: async (q, params) => ({ data: `executed: ${q}`, params })
      };
      const result = await resolver.resolveWithCache(
        operation, variables || {}, selections || [], context
      );
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify(result));
    } catch (err) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: err.message }));
    }
  });
});

cacheClient.registerShutdown(() => {
  return new Promise(resolve => server.close(resolve));
});

process.on('SIGTERM', () => cacheClient.gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => cacheClient.gracefulShutdown('SIGINT'));

server.listen(4000, () => console.log('GraphQL cache proxy on :4000'));
